
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_tw1_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_tw1", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.449280779138346e+01, 9.083254761204613e+01, 8.582717315616650e+01, 7.913164746123270e+01, 7.045333103165758e+01, 5.969935246424536e+01, 4.719497100686695e+01, 3.389689938902249e+01, 2.139270382809544e+01, 1.141674961598302e+01, 5.049382201777934e+00, 2.542737259517398e+00, 1.914414340398744e+00, 1.274674540130554e+00, 6.457877128781145e-01, 2.424157953051193e-01, 6.085532239857069e-02, 7.517432038180161e-03, 3.482660866126208e-04, 4.369514629452249e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


